// import Vue from 'vue'
import { createApp } from 'vue'
import App from './App.vue'
import router from './router'
import store from './store'
import installElementPlus from './plugins/element'
import vueaxios from 'vue-axios'
import axios from 'axios'
import { ElMessage } from 'element-plus'
import * as ElementPlusIconsVue from '@element-plus/icons-vue'
import JsonExcel from "vue-json-excel3"

const app = createApp(App)
installElementPlus(app)
app.use(store).use(router).mount('#app')

// Empty in dev, so "/api/..." stays relative and the devServer proxy handles it.
// A static host (gh-pages) has no proxy, so the build injects the backend origin.
axios.defaults.baseURL = process.env.VUE_APP_API_BASE_URL || ""

// 全域 API 錯誤提示：任何請求失敗都會跳出訊息，個別頁面不需再自行處理
const actionText = { get: '讀取資料', post: '新增', put: '更新', delete: '刪除' }
axios.interceptors.response.use(
    (response) => response,
    (error) => {
        const method = (error.config && error.config.method || '').toLowerCase()
        const url = (error.config && error.config.url) || ''
        const data = error.response && error.response.data
        const serverMsg = (typeof data === 'string' && data) || (data && data.message) || error.message
        const action = url.includes('/api/user/login') ? '登入' : (actionText[method] || '操作')
        ElMessage.error(`${action}失敗：${serverMsg}`)
        return Promise.reject(error)
    }
)

app.use(vueaxios, axios)
app.component("downloadExcel", JsonExcel);
for (const [key, component] of Object.entries(ElementPlusIconsVue)) {
    app.component(key, component)
}
